<?php
require_once __DIR__.'/../includes/functions.php';wajibRole('admin');if($_SERVER['REQUEST_METHOD']==='POST'){csrfCheck();$id=(int)$_POST['id'];$act=$_POST['aksi']??'';$note=trim($_POST['catatan']??'');$s=$koneksi->prepare('SELECT k.id_laporan,k.id_user,k.status_klaim,l.nama_barang FROM klaim k JOIN laporan l ON l.id_laporan=k.id_laporan WHERE k.id_klaim=?');$s->bind_param('i',$id);$s->execute();$k=$s->get_result()->fetch_assoc();if($k){if($act==='setuju'){$q=$koneksi->prepare("SELECT COUNT(*) FROM klaim WHERE id_laporan=? AND status_klaim IN ('disetujui','diambil') AND id_klaim<>?");$q->bind_param('ii',$k['id_laporan'],$id);$q->execute();if((int)$q->get_result()->fetch_row()[0]===0){$st='disetujui';$s=$koneksi->prepare('UPDATE klaim SET status_klaim=?,catatan_admin=? WHERE id_klaim=?');$s->bind_param('ssi',$st,$note,$id);$s->execute();$s=$koneksi->prepare("UPDATE klaim SET status_klaim='ditolak',catatan_admin='Klaim lain telah disetujui.' WHERE id_laporan=? AND id_klaim<>? AND status_klaim='menunggu'");$s->bind_param('ii',$k['id_laporan'],$id);$s->execute();notifyUser($koneksi,(int)$k['id_user'],'Klaim disetujui','Klaim '.$k['nama_barang'].' disetujui. Silakan ikuti arahan sekolah.','siswa/klaim.php');flash('Klaim disetujui.');}else flash('Sudah ada klaim lain yang disetujui.','error');}elseif($act==='tolak'){$st='ditolak';$s=$koneksi->prepare('UPDATE klaim SET status_klaim=?,catatan_admin=? WHERE id_klaim=?');$s->bind_param('ssi',$st,$note,$id);$s->execute();notifyUser($koneksi,(int)$k['id_user'],'Klaim ditolak','Klaim '.$k['nama_barang'].' ditolak. Catatan: '.$note,'siswa/klaim.php');flash('Klaim ditolak.');}}redirect('admin/klaim.php');}$pageTitle='Klaim Barang';$rows=$koneksi->query('SELECT k.*,l.nama_barang,u.nama AS pemohon FROM klaim k JOIN laporan l ON l.id_laporan=k.id_laporan JOIN users u ON u.id_user=k.id_user ORDER BY k.created_at DESC');require __DIR__.'/../includes/header.php';?><div class="panel"><h2>Verifikasi klaim barang</h2><div class="table-wrap"><table><tr><th>Barang</th><th>Pemohon</th><th>Bukti kepemilikan</th><th>Status</th><th>Tindakan</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['nama_barang'])?></td><td><?=e($r['pemohon'])?></td><td style="max-width:240px"><?=e($r['bukti_kepemilikan'])?></td><td><span class="badge <?=e($r['status_klaim'])?>"><?=e(statusLabel($r['status_klaim']))?></span></td><td><?php if($r['status_klaim']==='menunggu'):?><form method="post" style="min-width:170px"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="id" value="<?=$r['id_klaim']?>"><input class="search" name="catatan" placeholder="Catatan (opsional)" style="margin-bottom:5px"><div class="actions"><button name="aksi" value="setuju" class="btn success sm">Setujui</button><button name="aksi" value="tolak" class="btn danger sm">Tolak</button></div></form><?php else:?><?=e($r['catatan_admin']??'-')?><?php endif;?></td></tr><?php endwhile;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
